"use client";

import { ConnectionSurface, connectionTarget } from "@diax/react/connect";
import { DecisionNode, DiagramFrame, EvidenceNode, SystemNode } from "@diax/ui-react/presentation";
import type { DiaxRelation } from "diax";
import { Check, GitPullRequestArrow, X } from "lucide-react";
import type { ReactNode } from "react";

const checks = ["Static analysis", "Type coverage", "Supply chain", "Contract tests"] as const;

const relations: readonly DiaxRelation<ReactNode>[] = [
  {
    id: "collect-normalize",
    from: "collect",
    to: "normalize",
    color: "#25879a",
    targetMarker: "arrow",
    gap: 8,
    label: <RelationLabel>Complete evidence</RelationLabel>,
  },
  {
    id: "normalize-decide",
    from: "normalize",
    to: "decide",
    color: "#7062b7",
    targetMarker: "arrow",
    gap: 8,
    label: <RelationLabel>Policy input</RelationLabel>,
  },
];

export default function ReleaseGateDecision() {
  return (
    <DiagramFrame
      data-showcase-corpus="release-gate-decision"
      eyebrow="Decision architecture · Authored DOM"
      title="Collect evidence. Decide once."
      description="A gate can preserve every diagnostic without turning every tool failure into a fragmented developer loop."
      icon={<GitPullRequestArrow aria-hidden="true" />}
      caption="Comparison is native HTML. Only the reviewable evidence chain participates in connection geometry."
      className="w-full max-w-[1120px] [--diax-accent:#8b7ad1] [--diax-frame-bg:#0a1117] [--diax-frame-radius:3px] [--diax-frame-shadow:none] [--diax-node-bg:#111b24] [--diax-node-border:#344451] [--diax-node-shadow:none] [--diax-node-text:#e5edf2] [--diax-ui-radius:3px]"
    >
      <section className="grid gap-3 md:grid-cols-2" aria-label="Quality gate behavior comparison">
        <ComparisonCard
          label="Fail-fast"
          title="First failure ends the run"
          summary="Developers repair one tool at a time and repeatedly wait for the same pipeline."
          status="failure"
        />
        <ComparisonCard
          label="Delayed decision"
          title="Every check reports before policy runs"
          summary="One execution returns the complete evidence set and a single accountable verdict."
          status="success"
        />
      </section>

      <div className="my-5 flex items-center gap-3" aria-hidden="true">
        <span className="h-px flex-1 bg-slate-700" />
        <span className="font-mono text-[9px] font-bold uppercase tracking-[0.12em] text-slate-500">
          Reviewable evidence path
        </span>
        <span className="h-px flex-1 bg-slate-700" />
      </div>

      <ConnectionSurface
        relations={relations}
        pathType="orthogonal"
        aria-label="Delayed release decision relationships"
        className="grid gap-20 py-2 sm:grid-cols-3 sm:gap-12 sm:py-5"
      >
        <EvidenceNode
          {...connectionTarget("collect")}
          title="Run every check"
          source="lint · types · dependencies · tests"
          sourceLabel="Inputs"
          strength="high"
          description="Failures become evidence records instead of immediate process exits."
          className="relative max-w-none"
        />
        <SystemNode
          {...connectionTarget("normalize")}
          name="Normalize results"
          kind="Policy boundary"
          status="healthy"
          tags={["severity", "scope", "source"]}
          description="Translate tool-specific output into one stable decision contract."
          className="relative max-w-none"
        />
        <DecisionNode
          {...connectionTarget("decide")}
          title="Evaluate once"
          outcome="Pass or fail with full context"
          criteria={[
            "All tools completed",
            "Thresholds are versioned",
            "Diagnostics remain actionable",
          ]}
          status="approved"
          owner="Release policy"
          className="relative max-w-none"
        />
      </ConnectionSurface>

      <dl className="m-0 mt-5 grid grid-cols-3 border-y border-slate-700 text-center">
        <GateMetric label="Pipeline verdicts" value="1" />
        <GateMetric label="Evidence sources" value="4" />
        <GateMetric label="Hidden failures" value="0" />
      </dl>
    </DiagramFrame>
  );
}

function ComparisonCard({
  label,
  title,
  summary,
  status,
}: {
  label: string;
  title: string;
  summary: string;
  status: "failure" | "success";
}) {
  const failure = status === "failure";
  return (
    <article className="border border-slate-700 bg-[#0d161e] p-4">
      <div className="flex items-center justify-between gap-3 border-b border-slate-700 pb-3">
        <span
          className={`font-mono text-[9px] font-bold uppercase tracking-[0.1em] ${failure ? "text-rose-300" : "text-emerald-300"}`}
        >
          {label}
        </span>
        {failure ? (
          <X aria-hidden="true" className="size-4 text-rose-300" />
        ) : (
          <Check aria-hidden="true" className="size-4 text-emerald-300" />
        )}
      </div>
      <h2 className="m-0 mt-3 text-sm font-semibold text-slate-100">{title}</h2>
      <p className="m-0 mt-1 text-[11px] leading-relaxed text-slate-400">{summary}</p>
      <ol className="m-0 mt-4 grid list-none grid-cols-2 gap-px bg-slate-700 p-px">
        {checks.map((check, index) => {
          const skipped = failure && index > 0;
          return (
            <li
              key={check}
              className={`flex items-center gap-1.5 bg-[#111b24] px-2 py-2 text-[9px] ${skipped ? "text-slate-600" : "text-slate-300"}`}
            >
              <span
                aria-hidden="true"
                className={`size-1.5 ${skipped ? "bg-slate-700" : failure ? "bg-rose-400" : "bg-emerald-400"}`}
              />
              {check}
            </li>
          );
        })}
      </ol>
    </article>
  );
}

function GateMetric({ label, value }: { label: string; value: string }) {
  return (
    <div className="border-l border-slate-700 px-2 py-3 first:border-l-0">
      <dt className="text-[8px] font-semibold uppercase tracking-[0.08em] text-slate-500">
        {label}
      </dt>
      <dd className="m-0 mt-1 font-mono text-xl font-bold text-slate-100">{value}</dd>
    </div>
  );
}

function RelationLabel({ children }: { children: ReactNode }) {
  return (
    <span className="border border-slate-600 bg-[#0a1117] px-2 py-1 font-mono text-[8px] font-bold uppercase tracking-[0.06em] text-slate-300">
      {children}
    </span>
  );
}
